<?php
declare(strict_types=1);require_once __DIR__.'/_bootstrap.php';$rows=$db->query("SELECT DATE(creado_en) fecha,COUNT(*) pedidos,SUM(CASE WHEN estado_pago='approved' THEN total ELSE 0 END) ventas_aprobadas,SUM(total) valor_pedidos FROM pedidos GROUP BY DATE(creado_en) ORDER BY fecha DESC LIMIT 90")->fetchAll();adminStart('Ventas');?><div class="table-wrap"><table class="table"><thead><tr><th>Fecha</th><th>Pedidos</th><th>Ventas aprobadas</th><th>Valor de pedidos</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=Security::e($r['fecha'])?></td><td><?=(int)$r['pedidos']?></td><td>$<?=number_format((float)$r['ventas_aprobadas'],0)?></td><td>$<?=number_format((float)$r['valor_pedidos'],0)?></td></tr><?php endforeach;?></tbody></table></div><?php adminEnd();?>
